@startuml

abstract class Person {
  + FirstName : string
  + LastName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Center {
  + Name : string
  + Address : string
}

class Room {
  + MaxCapacity : int
  + RoomNumber : int
}

abstract class Session {
  + Date : date
  + StartHour : time
}

class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {}

abstract class Participant {
  + Person "1" -- "0..*" Session
}

class TrainerSupervision {
  + Trainer "1" -- "0..*" GroupSession
}

Person "1" -- "*" Participant
Trainer "1" -- "*" TrainerSupervision

Center "1" *-- "*" Room
Room "1" *-- "*" Participant
Room "1" *-- "*" TrainerSupervision

GroupSession "1" -- "1" TrainerSupervision
IndividualSession "0..*" -- "0..*" Participant

@enduml

